/**
 * Unit tests for MappingIterator.close()
 */
public class MappingIterator_close_TriageGen2Test {

    @Test
    public void testClose_WhenParserIsNull() throws IOException {
        // Since MappingIterator is an abstract class or has a protected constructor,
        // and we need to test the logic where _parser is null.
        // We use Mockito to create a spy/mock of the class.

        MappingIterator<Object> iterator = mock(MappingIterator.class, withSettings()
                .useConstructor()
                .defaultAnswer(CALLS_REAL_METHODS));

        // We cannot easily set the private field _parser via standard API, 
        // but the logic is: if (_parser != null) { _parser.close(); }
        // If we mock the class and don't trigger any logic that initializes _parser, 
        // it remains null.

        iterator.close();

        // Verify no interaction with a non-existent parser (implicitly tests the null check)
        verify(iterator, times(1)).close();
    }

    @Test
    public void testClose_WhenParserIsNotNull() throws IOException {
        // We need to test the branch where _parser != null
        // Because MappingIterator is complex, we mock the JsonParser 
        // and use a concrete subclass or a spy to simulate the internal state.

        JsonParser mockParser = mock(JsonParser.class);

        // MappingIterator is typically created via ObjectMapper.readValues().
        // To test this specific method's coverage, we mock the behavior of the iterator.
        MappingIterator<Object> iterator = mock(MappingIterator.class, withSettings()
                .useConstructor()
                .defaultAnswer(CALLS_REAL_METHODS));

        // We simulate the internal state where _parser is not null.
        // In a real Jackson environment, _parser is a private field.
        // To achieve maximum coverage on the provided snippet:
        // if (_parser != null) { _parser.close(); }

        // We use a spy on a real instance if possible, or mock the method call.
        // Since we are testing the implementation of the method itself:

        MappingIterator<Object> spyIterator = spy(new MappingIterator<Object>(null, null, null, null) {
            // This is a hack to access the protected/private logic via a subclass for testing
            // However, since we can't easily inject the private _parser without reflection:
        });

        // Let's use reflection to set the private field _parser to ensure branch coverage
        try {
            java.lang.reflect.Field parserField = MappingIterator.class.getDeclaredField("_parser");
            parserField.setAccessible(true);
            parserField.set(spyIterator, mockParser);
        } catch (Exception e) {
            // If field name differs in specific Jackson versions, this is the fallback
            throw new RuntimeException(e);
        }

        spyIterator.close();

        // Verify the parser.close() was called
        verify(mockParser, times(1)).close();
    }

    @Test(expected = IOException.class)
    public void testClose_WhenParserThrowsIOException() throws IOException {
        JsonParser mockParser = mock(JsonParser.class);
        doThrow(new IOException("Simulated IO Error")).when(mockParser).close();

        MappingIterator<Object> spyIterator = spy(new MappingIterator<Object>(null, null, null, null) {
        });

        try {
            java.lang.reflect.Field parserField = MappingIterator.class.getDeclaredField("_parser");
            parserField.setAccessible(true);
            parserField.set(spyIterator, mockParser);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        spyIterator.close();
    }
}
